	["instance:860"]={
		kind="instance",
		name="Return to Karazhan",
		expansion=7,
		expansions={7},
		instanceID=860,
		mapID=1651,
		uiMapID=812,
		areaID=3457,
		parentUiMapID=42,
		flags=0,
		order=0,
		instanceType="party",
		lore="From the moment of its mysterious creation, the purpose of this dark tower has been intertwined with the history of the Guardians of Tirisfal, once Azeroth's greatest bulwark against the Legion. It is now best known as the home of Medivh, who tragically betrayed Azeroth and brought the unbroken chain of Guardians to an end. This legacy makes Karazhan a place of particular interest for the Legion, who have descended in full force in an effort to open a new front in their war on the denizens of Azeroth.",
		art={button=1537283,background=1537279,lore=1537281},
		difficultyIDs={2,8,23},
