	["instance:875"]={
		kind="instance",
		name="Tomb of Sargeras",
		expansion=7,
		expansions={7},
		instanceID=875,
		mapID=1676,
		uiMapID=850,
		parentUiMapID=646,
		flags=0,
		order=5,
		instanceType="raid",
		lore="Aegwynn used this sacred temple of Elune to lock away the defeated Sargeras' avatar. She hoped it would remain dormant, buried deep within the earth, but the lure of power has continued to draw foul entities to this site. When Gul'dan re-entered the tomb, he tore down Aegwynn's wards and opened a doorway for the Legion to invade. Now, the fel army tears at the vault, hoping to reclaim their master's power.",
